import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
export const GP_ACTIVATION_PATHS=Object.freeze(['wrangler.jsonc','wrangler.coaching.jsonc','wrangler.hq-management.jsonc']);
export const GP_ACTIVATION_AUTHORITY=Object.freeze({owner:'Matt',integrationIssue:1065,instruction:'Deploy A021 code first, then enable the existing V2 directory for members and HQ.',originalSource:'0ae606fe5fd254cf717c3a853d7829801aaa8934',originalTree:'b132bc8866b64c7e131cbcc5a1d7c9d5078e1462',originalPhysicalConfigurations:['wrangler.jsonc','wrangler.hq-management.jsonc'],mirroredConfiguration:'wrangler.coaching.jsonc',directoryVersion:'672021e21d318162d9aa550f',gpNotifications:false,clinicalRegistrationVerified:false,stockChanged:false,emailAuthority:false,customerDataChanged:false,reimport:false,spendingGranted:false,genericAdoptionAllowed:false,rollbackAuthorityBroadened:false});
export const GP_ACTIVATION_ORIGINAL_BLOBS=Object.freeze({'wrangler.jsonc':{before:'48adc3e7d61e4b97c52ac4cbe1751d15117a26cd',after:'6b5d8e1fb11d1aa8b7bb230b4cc4332facef20af'},'wrangler.hq-management.jsonc':{before:'b4cd2b34d6fd953af0398f422bc034e9276c84db',after:'a438e62b346f207222640a94d8012c196eab9cfd'}});
const CORE_BEFORE='    "MEMBER_GP_LOOKUP_ENABLED": "true",\n',CORE_AFTER=CORE_BEFORE+'    "MEMBER_GP_DIRECTORY_V2_ENABLED": "true",\n';
const HQ_BEFORE='    "ALLOWED_ORIGINS": "https://hq.shiftsometimber.co.uk"\n',HQ_AFTER='    "ALLOWED_ORIGINS": "https://hq.shiftsometimber.co.uk",\n    "MEMBER_GP_DIRECTORY_V2_ENABLED": "true"\n';
const pair=path=>{assert(GP_ACTIVATION_PATHS.includes(path),'Only the three existing physical GP configurations are authorised');return path==='wrangler.hq-management.jsonc'?[HQ_BEFORE,HQ_AFTER]:[CORE_BEFORE,CORE_AFTER];};
const once=(s,a,b)=>{assert.equal(s.split(a).length,2,'Exactly one literal GP directory flag location required');return s.replace(a,b);};
export function enableGpDirectoryConfiguration(path,before){assert(!/"MEMBER_GP_DIRECTORY_V2_ENABLED"\s*:/.test(before),'Accepted GP-code configuration must have the V2 flag absent');return once(before,...pair(path));}
export function disableGpDirectoryConfiguration(path,after){const[before,current]=pair(path);assert.equal((after.match(/"MEMBER_GP_DIRECTORY_V2_ENABLED"\s*:/g)||[]).length,1,'Exactly one V2 flag may exist');return once(after,current,before);}
export const gpActivationSha256=value=>createHash('sha256').update(value).digest('hex');
export function gpActivationBindingsSha256(bindings){assert(Array.isArray(bindings),'Actual provider bindings required');const names=new Set();for(const b of bindings){assert(typeof b.name==='string'&&b.name&&typeof b.type==='string');assert(!names.has(b.name),'Duplicate provider binding refused');names.add(b.name);}const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,stable(x[k])])):x;return gpActivationSha256(JSON.stringify(bindings.filter(b=>b.name!=='MEMBER_GP_DIRECTORY_V2_ENABLED').map(stable).sort((a,b)=>a.name.localeCompare(b.name))));}
export const gpActivationGitBlob=value=>{const b=Buffer.from(value);return createHash('sha1').update('blob '+b.length+'\0').update(b).digest('hex');};
export function validateGpActivationConfigurations(before,after){assert.equal(before['wrangler.jsonc'],before['wrangler.coaching.jsonc'],'Accepted core/coaching source must already be byte-identical');assert.equal(after['wrangler.jsonc'],after['wrangler.coaching.jsonc'],'Activated core/coaching source must remain byte-identical');for(const path of GP_ACTIVATION_PATHS){assert.equal(after[path],enableGpDirectoryConfiguration(path,before[path]));assert.equal(disableGpDirectoryConfiguration(path,after[path]),before[path],'Every unrelated binding and configuration byte must remain: '+path);}return true;}
const sha40=s=>assert.match(s||'',/^[a-f0-9]{40}$/),sha64=s=>assert.match(s||'',/^[a-f0-9]{64}$/),uuid=s=>assert.match(s||'',/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i);
function terminal(run,base,path){assert.equal(run.status,'completed');assert.equal(run.conclusion,'success');assert.equal(run.head_sha,base);assert.equal(run.head_branch,'main');assert.equal(run.path,path);assert.equal(run.head_repository?.full_name,'shiftsometimber/shift-core');assert(['push','workflow_dispatch'].includes(run.event));assert(Number.isSafeInteger(run.id)&&run.id>0);assert.equal(run.html_url,'https://github.com/shiftsometimber/shift-core/actions/runs/'+run.id);}
function provider(row,source,run,{partners=false}={}){assert.equal(row.source,source);assert.equal(row.run,run.id);uuid(row.deploymentId);uuid(row.versionId);assert.equal(row.percentage,100);assert.equal(row.gpEnabled,false,'Code must actually be serving with the GP directory OFF');if(partners)assert.equal(row.partnersEnabled,true);sha64(row.bundleSha256);sha64(row.otherBindingsSha256);assert(Number.isSafeInteger(row.bundleBytes)&&row.bundleBytes>0);}
export function validateGpActivationInputs({acceptedBase,coreRun,hqRun,live,liveSha256,liveBytes,now=Date.now()}){
 sha40(acceptedBase);sha64(liveSha256);assert.equal(gpActivationSha256(liveBytes),liveSha256,'Expected current live receipt identity required');assert.deepEqual(JSON.parse(liveBytes),live);
 const captured=Date.parse(live.capturedAt);assert(Number.isFinite(captured)&&Number.isFinite(now)&&captured<=now&&now-captured<=900000,'Fresh dated live receipt within 15 minutes required');
 terminal(coreRun,acceptedBase,'.github/workflows/cloudflare-production-promote.yml');terminal(hqRun,acceptedBase,'.github/workflows/hq-management-release.yml');
 assert.equal(live.schema,'shift-gp-code-before-directory-activation/v1');assert.equal(live.source,acceptedBase);assert.equal(live.main,acceptedBase);
 provider(live.core,acceptedBase,coreRun);provider(live.hq,acceptedBase,hqRun,{partners:true});
 const h=live.staticHq;assert.equal(h.repository,'shiftsometimber/shift-hq');sha40(h.source);assert.equal(h.tree,'a5a7d21d9a6e92e6a1a49554f718b586be14622a');assert.equal(h.approvedPrHead,'7a0087c075c674828313ec9b1048165275c244d8');uuid(h.deploymentId);uuid(h.versionId);assert.equal(h.percentage,100);assert.equal(h.assetsVerified,true);sha64(h.gpModuleSha256);
 assert.equal(live.directory.version,GP_ACTIVATION_AUTHORITY.directoryVersion);assert.equal(live.directory.complete,1);assert.equal(live.directory.productionWrites,0);
 const m=live.memberCode;assert.equal(m.source,acceptedBase);assert.equal(m.status,'code_only_verified');assert.equal(m.flagsOff,true);assert.equal(m.featureAcceptance,false);assert.equal(m.realCustomerWrites,0);assert.equal(m.notificationsSent,0);assert.equal(m.assetsBefore.length,3);assert.deepEqual(m.assetsAfter,m.assetsBefore);for(const a of m.assetsBefore){assert(['https://shiftsometimber.co.uk/assets/member-experience/member-details.mjs','https://shiftsometimber.co.uk/assets/member-experience/member-details.css','https://shiftsometimber.co.uk/assets/member-experience/gp-form.mjs'].includes(a.url));sha64(a.sha256);}assert.equal(new Set(m.assetsBefore.map(a=>a.url)).size,3);
 assert.equal(typeof live.hqSignedInAcceptance,'boolean','Source/code receipt must distinguish genuine HQ holder acceptance');
 return {source:acceptedBase,capturedAt:live.capturedAt,coreRun:coreRun.id,hqRun:hqRun.id,liveSha256,core:{...live.core},hq:{...live.hq},staticHq:{...h},directory:{...live.directory},featureAcceptance:false,finalHolderAcceptanceStillRequired:true};
}
